async function lockOffer(tx: Tx, where: SQL): Promise<OfferEntry | undefined> {
  const [entry] = await tx.select().from(s.waitlistEntries).where(where).for("update");
  return entry;
}

/** Ends an outstanding offer and passes its slot to the next client in line. */
async function closeOffer(tx: Tx, entry: OfferEntry, status: "declined" | "expired"): Promise<void> {
  const startMs = entry.offerSlotStartAt!.getTime();
  const slot = {
    staffId: entry.offerStaffId!,
    serviceId: entry.serviceId,
    startMs,
    endMs: entry.offerSlotEndAt!.getTime(),
  };

  await tx.update(s.waitlistEntries).set({ status }).where(eq(s.waitlistEntries.id, entry.id));
  await cancelByDedupeKey(tx, `waitlist.expire:${entry.id}:${startMs}`);
  await enqueue(tx, {
    businessId: entry.businessId,
    topic: "waitlist.slot_freed",
    payload: slot,
    dedupeKey: `waitlist.refree:${entry.id}:${startMs}`,
  });
