describe("declining an offer", () => {
  const offers = () => db.select().from(s.outbox).where(eq(s.outbox.topic, "waitlist.offer"));

  async function offerToFirstOfTwo() {
    const booked = await book();
    await join("+77012222222");
    await join("+77013333333");
    await cancel((booked as { bookingId: string }).bookingId);
    await drainOnce();
    return (await entries()).find((r) => r.status === "offered")!;
  }

  it("passes the slot to the next client straight away", async () => {
    const first = await offerToFirstOfTwo();
    expect(await declineOffer(first.offerToken!)).toEqual({ ok: true });
    await drainOnce(); // slot_freed -> offer to the next client
    await drainOnce(); // deliver it

    const rows = await entries();
    expect(rows.find((r) => r.id === first.id)!.status).toBe("declined");
    const second = rows.find((r) => r.status === "offered")!;
    const [client] = await db.select().from(s.clients).where(eq(s.clients.id, second.clientId));
    expect(client.phone).toBe("+77013333333");
  });

  it("returns the slot to public stock when nobody else is waiting", async () => {
    const booked = await book();
    await join("+77012222222");
    await cancel((booked as { bookingId: string }).bookingId);
    await drainOnce();

    const only = (await entries()).find((r) => r.status === "offered")!;
    await declineOffer(only.offerToken!);

    const free = await getAvailability({
      businessId: f.business.id,
      timeZone: f.business.timezone,
      staffId: f.master.id,
      serviceId: f.service.id,
      dateISO: date,
    });
    expect(free.map((sl) => sl.startMs)).toContain(slotAt().startMs);
  });

  it("is idempotent: a double tap offers the slot onward once", async () => {
    const first = await offerToFirstOfTwo();
    expect(await declineOffer(first.offerToken!)).toEqual({ ok: true });
    expect(await declineOffer(first.offerToken!)).toEqual({ ok: true });
    await drainOnce();
    await drainOnce();

    expect(await offers()).toHaveLength(2); // one for the first client, one for the second
    expect((await entries()).filter((r) => r.status === "offered")).toHaveLength(1);
  });

  it("kills the link: it can no longer be claimed", async () => {
    const first = await offerToFirstOfTwo();
    await declineOffer(first.offerToken!);
    expect(await acceptOffer(first.offerToken!)).toEqual({ ok: false, error: "expired" });
  });

  it("does nothing to a booking that was already claimed", async () => {
    const first = await offerToFirstOfTwo();
    expect((await acceptOffer(first.offerToken!)).ok).toBe(true);

    expect(await declineOffer(first.offerToken!)).toEqual({ ok: false, error: "expired" });
    await drainOnce();

    expect((await entries()).find((r) => r.id === first.id)!.status).toBe("booked");
    expect(await db.select().from(s.bookings).where(eq(s.bookings.status, "confirmed")))
      .toHaveLength(1);
    expect((await entries()).filter((r) => r.status === "offered")).toHaveLength(0);
    expect(await offers()).toHaveLength(1);
  });
});

